package fixture

import (
	"bytes"
	"fmt"
	"go/format"
	"slices"
)

// gofakeitImport is the import path of the faker the generated code calls.
const gofakeitImport = "github.com/brianvoe/gofakeit/v7"

// EmitParams describes one generation run.
type EmitParams struct {
	// PackageName is the package name of the generated file.
	PackageName string
	// SourceName is the source package name, used as the type qualifier.
	SourceName string
	// SourcePath is the source package import path.
	SourcePath string
	// Imports holds every import path the fixture expressions need, as Plans
	// reports them.
	Imports []string
	// Plans holds the fixture bodies in output order.
	Plans []Plan
}

// generateHelper wraps the two-value gofakeit.Generate so template fallbacks
// can be called inside composite literals.
const generateHelper = `
func mustGenerate(template string) string {
	s, err := gofakeit.Generate(template)
	if err != nil {
		panic(err)
	}
	return s
}
`

// Emit renders the generated fixture file, formatted with go/format. The
// output is deterministic: the same params produce byte-identical output.
func Emit(p EmitParams) ([]byte, error) {
	var buf bytes.Buffer

	buf.WriteString("// Code generated by kanna. DO NOT EDIT.\n\n")
	buf.WriteString("package " + p.PackageName + "\n")

	if len(p.Plans) > 0 {
		writeImports(&buf, p)
	}

	for _, pl := range p.Plans {
		writePlan(&buf, p.SourceName, pl)
	}

	if needsHelper(p.Plans) {
		buf.WriteString(generateHelper)
	}

	src, err := format.Source(buf.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format generated code: %w", err)
	}

	return src, nil
}

// writeImports emits the third-party group followed by the source package on its
// own, which is where gofmt would leave them and keeps the source package easy
// to spot.
func writeImports(buf *bytes.Buffer, p EmitParams) {
	deps := slices.Clone(p.Imports)
	slices.Sort(deps)

	buf.WriteString("\nimport (\n")

	for _, path := range deps {
		fmt.Fprintf(buf, "\t%q\n", path)
	}

	if len(deps) > 0 {
		buf.WriteString("\n")
	}

	fmt.Fprintf(buf, "\t%q\n)\n", p.SourcePath)
}

// needsHelper reports whether any expression calls mustGenerate, which then has
// to be defined in the same file.
func needsHelper(plans []Plan) bool {
	for _, pl := range plans {
		for _, f := range pl.Fields {
			if f.NeedsHelper {
				return true
			}
		}
	}

	return false
}

func writePlan(buf *bytes.Buffer, qualifier string, pl Plan) {
	typ := qualifier + "." + pl.Name

	fmt.Fprintf(buf, "\nfunc %s(setters ...func(m *%s)) %s {\n", pl.Name, typ, typ)

	if len(pl.Fields) == 0 {
		fmt.Fprintf(buf, "\tm := %s{}\n", typ)
	} else {
		fmt.Fprintf(buf, "\tm := %s{\n", typ)

		for _, f := range pl.Fields {
			fmt.Fprintf(buf, "\t\t%s: %s,\n", f.Name, f.Expr)
		}

		buf.WriteString("\t}\n")
	}

	buf.WriteString("\tfor _, s := range setters {\n\t\ts(&m)\n\t}\n\treturn m\n}\n")
}
